//! Zenith Universal Meta-Compiler (UMC) Optimizer
//!
//! This module implements the optimization phase of the Zenith compiler.
//! It takes the Universal Meta-Compiler Intermediate Representation (UMC IR)
//! generated by the `ir_gen` module and applies a series of transformations
//! to improve the performance, efficiency, and resource utilization of the code.
//!
//! The optimizer is designed to handle the diverse computational paradigms of Zenith,
//! incorporating classical, quantum, nano, and multi-timeline specific optimization passes.
//!
//! Key responsibilities include:
//! - **General Optimizations:** Standard compiler optimizations applicable to any paradigm.
//! - **Quantum Optimizations:** Specialized passes for quantum circuits and operations.
//! - **Nano-Agent Optimizations:** Optimizations tailored for resource-constrained nano-agent execution.
//! - **Multi-Timeline System (MTS) Optimizations:** Temporal reasoning and causality-aware optimizations.
//! - **Linear/Affine Type Optimizations:** Resource management and usage pattern analysis.
//! - **Sankofa Memory Optimizations:** Optimizing access patterns and consistency checks for temporal memory.
//! - **Optimization Passes Management:** Orchestrating the order and application of various passes.

use crate::ir_gen::{IrInstruction, IrValue, IrRegister, IrType, IrGenError}; // Import IR structures
use crate::ast::Span; // For error reporting in optimizations
use std::collections::{HashMap, HashSet};

/// Represents an optimization pass within the UMC Optimizer.
pub trait OptimizationPass {
    /// The name of the optimization pass.
    fn name(&self) -> &'static str;
    /// Applies the optimization pass to the given IR, returning true if any changes were made.
    fn run(&self, ir: &mut Vec<IrInstruction>) -> bool;
}

// --- UMC Optimizer Structure ---
pub struct UMC_Optimizer {
    pub optimization_passes: Vec<Box<dyn OptimizationPass>>,
    pub metrics: OptimizationMetrics,
    pub errors: Vec<OptimizerError>,
}

// --- Optimization Metrics ---
#[derive(Debug, Default)]
pub struct OptimizationMetrics {
    pub total_passes_run: usize,
    pub total_changes_made: usize,
    pub instruction_count_before: usize,
    pub instruction_count_after: usize,
    // Add more granular metrics as needed for different paradigms
    pub quantum_gate_optimizations: usize,
    pub nano_resource_optimizations: usize,
    pub mts_timeline_simplifications: usize,
    pub sankofa_access_optimizations: usize,
}

// --- OptimizerError Structure ---
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OptimizerError {
    pub message: String,
    pub span: Span, // Reference to the original IR instruction's conceptual span
}

impl UMC_Optimizer {
    pub fn new() -> Self {
        UMC_Optimizer {
            optimization_passes: Vec::new(),
            metrics: OptimizationMetrics::default(),
            errors: Vec::new(),
        }
    }

    /// Adds a general optimization pass to the optimizer pipeline.
    pub fn add_pass<P: OptimizationPass + 'static>(&mut self, pass: P) {
        self.optimization_passes.push(Box::new(pass));
    }

    /// Runs all registered optimization passes on the UMC IR.
    pub fn optimize(&mut self, ir: &mut Vec<IrInstruction>) -> Result<&OptimizationMetrics, Vec<OptimizerError>> {
        self.metrics.instruction_count_before = ir.len();
        self.metrics.total_passes_run = 0;
        self.metrics.total_changes_made = 0;

        let mut changed_in_iteration = true;
        // Run passes iteratively until no more changes are made (fixed-point iteration)
        while changed_in_iteration {
            changed_in_iteration = false;
            for pass in &self.optimization_passes {
                self.metrics.total_passes_run += 1;
                println!("Running optimization pass: {}", pass.name());
                if pass.run(ir) {
                    changed_in_iteration = true;
                    self.metrics.total_changes_made += 1;
                }
            }
        }

        self.metrics.instruction_count_after = ir.len();

        if !self.errors.is_empty() {
            Err(self.errors.clone())
        } else {
            Ok(&self.metrics)
        }
    }
}

